sys_script_include.script:
var JevAssetMaintenanceBridgeSNC = Class.create();
JevAssetMaintenanceBridgeSNC.prototype = {
    initialize: function() {},

    execute: function(input) {
        var question = this._extractQuestion(input);

        if (!question) {
            return { answer: "I could not find a question in that message." };
        }

        try {
            var promptData = {
                prompt: "TYPE:noul\nINSTRUCTIONS:" + question + "\nSTATE:" + question
            };

            var request = {
                executionRequests: [{
                    payload: { prompt: promptData.prompt },
                    capabilityId: "c92d573f3b93c7108263d1a693e45ac2",
                    meta: { skillConfigId: "e12d973f3b93c7108263d1a693e45a76" }
                }],
                mode: "sync"
            };

            var output = sn_one_extend.OneExtendUtil.execute(request)["capabilities"]["c92d573f3b93c7108263d1a693e45ac2"]["response"];
            var parsed = JSON.parse(output);
            var modelOutput = parsed.model_output || parsed;

            return { answer: Array.isArray(modelOutput) ? modelOutput.join("; ") : String(modelOutput) };
        } catch (e) {
            return { answer: "I could not get a decision from Jev right now.", debug_error: e.message };
        }
    },

    _extractQuestion: function(input) {
        if (!input) return "";
        if (typeof input === "string") return input;
        return input.utterance || input.query || input.text || input.message || input.data || "";
    },

    type: "JevAssetMaintenanceBridgeSNC"
};
